-- Parche IPSP · 2026-09-15
-- Amplía la beta sin borrar históricos ni recetas creadas manualmente.

alter table camps add column if not exists delivery_notes text;
alter table recipes add column if not exists base_ingredient text;
alter table recipes add column if not exists difficulty smallint not null default 1;
alter table recipes add column if not exists cooking_method text;
alter table recipes add column if not exists double_fry boolean not null default false;
alter table recipes add column if not exists sunday_roast boolean not null default false;
alter table recipes add column if not exists base_qty_per_person numeric;
alter table recipes add column if not exists base_unit text;
alter table recipes add column if not exists protein_qty_per_person numeric;
alter table recipes add column if not exists protein_unit text;
alter table recipes add column if not exists rice_mode text not null default 'default';
alter table recipes add column if not exists fixed_weekday smallint;
alter table recipes add column if not exists fixed_service text;
alter table recipes add column if not exists only_weekday smallint;
alter table menu_items add column if not exists execution_status text not null default 'pending';
alter table menu_items add column if not exists replacement_name text;

-- Reglas de proteína actualizadas. Los targets son máximos, no cuotas.
update proteins set breakfast_only=false, parity='impar', target_frequency=2, notes='Solo almuerzo; máximo semanal 2 sujeto a stock.' where id='sardina';
update proteins set breakfast_only=true, target_frequency=2 where id in ('atun','huevo');

-- El catálogo anterior queda disponible como histórico pero no entra al randomizador.
update recipes set active=false where source in ('Maestro de platos IPSP','Menú semana 37','Menú semana 38','Menú semana 39');

